"""Checks src/standalone/static_init.cpp (generated by tools/gen_static_init.py) against game.exe.

  - Every initialiser of the list 00783004-00783BB0 is there, once, in list order, and its statements
    are what decoding its instructions gives now (the same pattern: stores, float folds, calls with the
    same targets, conventions and arguments, atexit with the same exit function, the same guard bit).
    A difference means the file was edited by hand or is stale (a helper it inlines got registered, or
    one it calls got ported): run tools/gen_static_init.py.
  - Each address is where it belongs: stores, fills, float results and guards in .data (or its
    zero-filled tail), float and double operands in .rdata (or .data, an earlier fold's result), call targets and exit functions in .text,
    import slots in the import address table.
  - A float fold of .rdata literals (tagged, tools/rdata_literals.py; S18e1) gives the same float
    whether it is computed as the original does (x87 order, 53 bits) or as the compiler may fold it
    (C++ precedence, in double or in float).
  - src/standalone/static_exit.cpp (the exit functions no rewrite registers) is what their instructions
    decode to now, its addresses are where they belong (as above), and src/hook/function_sizes.inc and
    config/extra_function_sizes.csv give each exit function its decoded size.

usage: python tools/check_static_init.py [--exe game.exe]
exit code 1 on any problem
"""
import argparse, os, re, struct, sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import gen_static_init as gen  # noqa: E402
import rdata_literals as rdata  # noqa: E402

BLOCK = re.compile(r'^    // ([0-9A-F]{8}): [^\n]*\n    d\.Begin\(0x([0-9A-F]{8})\);\n((?:    (?!// )[^\n]*\n)*)', re.M)
WHERE = [   # (pattern, which group holds an address, sections it may be in)
    (re.compile(r'd\.(?:Store|StoreFloat|Fill|Once|NonZero|Release)\((0x[0-9A-F]{8})'), ('.data',)),
    (re.compile(r'd\.Dword\((0x[0-9A-F]{8})\)'), ('.rdata', '.data')),
    (re.compile(r'd\.(?:Float|Double)\((0x[0-9A-F]{8})\)'), ('.rdata', '.data')),   # .data: an earlier fold's result
    (re.compile(r'd\.(?:Cdecl|Stdcall|Thiscall|AtExit)\((0x[0-9A-F]{8})'), ('.text',)),
    (re.compile(r'd\.Thiscall\(0x[0-9A-F]{8}, (0x[0-9A-F]{8})'), ('.data',)),
]
IMPORT = re.compile(r'd\.Import\((0x[0-9A-F]{8})')
FOLD = re.compile(r'd\.StoreFloat\((0x[0-9A-F]{8}), (.*)\);')
FOLD_TOKEN = re.compile(rdata.TAG.pattern + r'|d\.(?:Float|Double|Log)\(|([-+*/])')


def f32(v):
    return struct.unpack('<f', struct.pack('<f', v))[0]


def fold_problems(img, body, initialiser):
    """A float fold of literals (S18e1) is folded by the compiler: in C++ precedence, at whatever
    precision. The original computes it in x87 order at 53 bits (VC6's _FPinit, 006EEF7C:
    _controlfp(_PC_53, _MCW_PC) before _initterm) and stores a float. Each fold must give the same
    float in x87 order at 53 bits, in C++ order at 53 bits and in C++ order rounding to float."""
    out = []
    for m in FOLD.finditer(body):
        values, ops = [], []
        for t in FOLD_TOKEN.finditer(m.group(2)):
            if t.group(4):
                ops.append(t.group(4))
                continue
            if t.group(2) is None:
                break   # a read or ln: computed at run time
            size = 4 if t.group(3) or t.group(1).rstrip(')').endswith(('f', 'F')) else 8
            values.append(struct.unpack('<f' if size == 4 else '<d', img.read(int(t.group(2), 16), size))[0])
        else:
            if len(values) != len(ops) + 1:
                out.append(f'{initialiser:08X}: {m.group(0)}: not a fold of literals')
                continue

            def x87(rnd):
                r = values[0]
                for op, v in zip(ops, values[1:]):
                    r = rnd({'+': r + v, '-': r - v, '*': r * v, '/': r / v}[op])
                return f32(r)

            def cpp(rnd):
                terms, signs, cur = [], [], values[0]
                for op, v in zip(ops, values[1:]):
                    if op in '*/':
                        cur = rnd(cur * v if op == '*' else cur / v)
                    else:
                        terms.append(cur)
                        signs.append(op)
                        cur = v
                r = terms[0] if terms else cur
                for op, v in zip(signs, terms[1:] + [cur]):
                    r = rnd(r + v if op == '+' else r - v)
                return f32(r)

            got = {x87(lambda v: v), cpp(lambda v: v), cpp(f32)}
            if len(got) != 1:
                out.append(f'{initialiser:08X}: {m.group(0)}: the compiler\'s fold may differ from the original\'s '
                           f'53-bit result ({sorted(got)}): keep the operands as reads')
    return out


def blocks(text):
    return [(int(m.group(1), 16), int(m.group(2), 16), m.group(3)) for m in BLOCK.finditer(text)]


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument('--exe')   # default: tools/exe_path.py
    args = ap.parse_args()
    img = gen.Image(gen.exe_path.resolve(args.exe))
    problems = []
    decoded, bad = gen.decode_all(img)
    problems += [f'not decoded: {b}' for b in bad]
    if not os.path.exists(gen.OUT):
        problems.append(f'{os.path.relpath(gen.OUT, gen.ROOT)} is missing (run tools/gen_static_init.py)')
        text = ''
    else:
        text = open(gen.OUT, encoding='utf-8').read()
    ours = blocks(text)
    want = blocks(gen.render(decoded)) if not bad else []
    listed = [img.dword(slot) for slot in range(gen.LIST_BEGIN, gen.LIST_END + 4, 4)]
    if [a for a, _, _ in ours] != listed:
        problems.append(f'the file has {len(ours)} initialiser(s), the list {len(listed)}; or not in list order')
    for a, begin, _ in ours:
        if a != begin:
            problems.append(f'{a:08X}: d.Begin({begin:08X}) names another initialiser')
    expected = {a: body for a, _, body in want}
    for a, _, body in ours:
        if a in expected and expected[a] != body:
            problems.append(f'{a:08X}: differs from what its instructions decode to now (run tools/gen_static_init.py)')
    if not problems and gen.render(decoded) != text:
        problems.append('the header or footer differs (run tools/gen_static_init.py)')
    exits, bad = gen.decode_exits(img, decoded)
    problems += [f'not decoded: {b}' for b in bad]
    exit_text = open(gen.OUT_EXIT, encoding='utf-8').read() if os.path.exists(gen.OUT_EXIT) else ''
    if not bad and gen.render_exits(exits) != exit_text:
        problems.append(f'{os.path.relpath(gen.OUT_EXIT, gen.ROOT)} differs from what the exit functions decode to now '
                        '(run tools/gen_static_init.py)')
    sizes = gen.load_sizes()
    extra = {}
    for row in open(gen.EXTRA_SIZES, encoding='utf-8').read().splitlines()[1:]:
        if row:
            extra[int(row.split(',')[0], 16)] = int(row.split(',')[1])
    for fn, _, _, size, _ in exits:
        if sizes.get(fn) != size or extra.get(fn) != size:
            problems.append(f'exit function {fn:08X}: {size} bytes, function_sizes.inc has {sizes.get(fn)}, '
                            f'extra_function_sizes.csv {extra.get(fn)} (run tools/gen_static_init.py)')
    iat = img.iat()
    cases = [(int(m.group(1), 16), m.group(2)) for m in
             re.finditer(r'^    case (0x[0-9A-F]{8}):[^\n]*\n((?:        (?!return)[^\n]*\n)*)', exit_text, re.M)]
    for a, body in cases:
        if img.section(a) != '.text':
            problems.append(f'exit function {a:08X} is in {img.section(a)}, not .text')
    for a, _, body in ours:
        problems += fold_problems(img, body, a)
    for a, _, body in ours + [(a, None, body) for a, body in cases]:
        for rx, sections in WHERE:
            for m in rx.finditer(body):
                v = int(m.group(1), 16)
                if img.section(v) not in sections:
                    problems.append(f'{a:08X}: {m.group(0)}...: {v:08X} is in {img.section(v)}, not {"/".join(sections)}')
        for m in IMPORT.finditer(body):
            v = int(m.group(1), 16)
            if not iat[0] <= v < iat[1]:
                problems.append(f'{a:08X}: import slot {v:08X} is outside the import address table')
    for p in problems:
        print('check_static_init:', p)
    calls = sum(len(re.findall(r'd\.(?:Cdecl|Stdcall|Thiscall|Import)\(', body)) for _, _, body in ours)
    atexits = sum(body.count('d.AtExit(') for _, _, body in ours)
    print(f'check_static_init: {len(ours)} static initialiser(s), {calls} call(s), {atexits} atexit, {len(exits)} exit '
          f'function(s) generated, {len(problems)} problem(s)')
    return 1 if problems else 0


if __name__ == '__main__':
    sys.exit(main())
